func toSortedText(str) =
  {
    {
      local l = []
      for (i: 1 .. str.textLen() step 1) {
        l.add(str.segment(i, 1))
      }
      l
        .sort { m, n -> m << n }.join("")
    }
  }

func isAnagram(a, b) =
  toSortedText(a) === toSortedText(b)

println(isAnagram("listen", "silent"))

