func topologicalSort(graph) =
  {
    {
      local inD = {  }
      for (u in graph.keys()) {
        if (!inD.containsKey(u)) {
          inD.set(u, 0)
        }
        for (v in graph.get(u, [])) {
          inD.set(v, inD.getAtPath([v], 0) + 1)
        }
      }
      local q = []
      for (k, v in inD) {
        if (v == 0) {
          q.add(k)
        }
      }
      local res = []
      while (q.listLen() > 0) {
        local u = q[1]
        q.remove(1)
        res.add(u)
        if (graph.containsKey(u)) {
          for (v in graph.get(u, [])) {
            inD.set(v, inD.get(v, []) - 1)
            if (inD.get(v, []) == 0) {
              q.add(v)
            }
          }
        }
      }
      res
    }
  }

1. Define topologicalSort(graph): Kahn's algorithm on an adjacency-list dict.
2. Build in-degree dict inD for all nodes.
3. Initialize queue q with nodes of in-degree 0.
4. While queue is not empty: dequeue u, add to result res.
5. For each neighbor v of u: decrement in-degree; if it reaches 0, enqueue v.
6. Return res (topological order).

func rotateChars(s, n) =
  {
    {
      local alpha = "abcdefghijklmnopqrstuvwxyz"
      local res = ""
      for (i: 1 .. s.textLen() step 1) {
        local ch = s.segment(i, 1)
        local lower = ch.lowercase()
        local idx = -1
        for (j: 1 .. 26 step 1) {
          if (alpha.segment(j, 1) === lower) {
            idx = j
          }
        }
        if (idx == -1) {
          res = res _ ch
        } else {
          local newCh = alpha.segment(idx + n - 1 % 26 + 1, 1)
          res = res _ (if (ch === lower) {
            newCh
          } else {
            newCh.uppercase()
          })
        }
      }
      res
    }
  }

1. Define rotateChars(s, n): applies ROT-n cipher to each letter.
2. Define alphabet string alpha.
3. For each character, find its index in alpha.
4. If not a letter, append as-is.
5. Otherwise compute new index using modular arithmetic and select new character.
6. Preserve original case (upper/lower).

