func interpolate(points, x) =
  {
    {
      local pt1 = points[1]
      local pt2 = points[points.listLen()]
      for (i: 1 .. points.listLen() - 1 step 1) {
        if (points[i][1] <= x && points[i + 1][1] >= x) {
          pt1 = points[i]
          pt2 = points[i + 1]
          break
        }
      }
        local t = if (pt2[1] == pt1[1]) {
          0
        } else {
          (x - pt1[1]) / (pt2[1] - pt1[1])
        }
        pt1[2] + (pt2[2] - pt1[2]) * t
    }
  }

1. Define interpolate(points, x): linear interpolation between nearest bracketing points.
2. Find pt1, pt2 where pt1[1] <= x <= pt2[1].
3. Compute t = (x - pt1[1]) / (pt2[1] - pt1[1]).
4. Return pt1[2] + (pt2[2] - pt1[2]) * t.

