  }

1. Define rotateMatrix90(m): rotates 3x3 matrix 90° clockwise.
2. New matrix: element at [i][j] comes from [n-j+1][i] of original.
3. Hard-coded for 3x3 using explicit indices.

func rollingMax(list) =
  {
    {
      local res = []
      local cur = list[1]
      for (x in list) {
        if (x > cur) {
          cur = x
        }
        res.add(cur)
      }
      res
    }
  }

1. Define rollingMax(list): running maximum.
2. Initialize cur = list[1].
3. For each x: update cur if x > cur; append cur to result.

func pairwiseSum(list) =
  {
    {
      local res = []
      for (i: 1 .. list.listLen() - 1 step 1) {
        res.add(list[i] + list[i + 1])
      }
      res
    }
  }

1. Define pairwiseSum(list): sums adjacent pairs.
2. Loop i from 1 to len-1.
3. Add list[i] + list[i+1] to result.

func cartesianProduct(a, b) =
  {
    {
      local res = []
      for (x in a) {
        for (y in b) {
          res.add([x, y])
        }
      }
      res
    }
  }

1. Define cartesianProduct(a, b): all pairs from a and b.
2. Nested for-each loops.
3. Add [x, y] pair to result.

func shuffle(list) =
  {
    {
      local res = copyList(list)
      for (i: 1 .. res.listLen() step 1) {
        local j = randInt(1, res.listLen())
        local temp = res[i]
        res[i] = res[j]
        res[j] = temp
      }
      res
    }
  }

1. Define shuffle(list): pseudo-random reorder using swaps.
2. Copy list to avoid mutation.
3. For each index i: pick random j; swap res[i] and res[j].

func removeOutliers(list) =
  {
      local avg = avgOf(list)
      local dev = stdDevOf(list)
      list
        .filter { x -> abs(x - avg) <= 2 * dev }
  }

1. Define removeOutliers(list): remove elements beyond 2 standard deviations.
2. Compute avg and stdDev using built-ins.
3. Filter: keep x where |x - avg| <= 2 * dev.

func zipToDict(keys, values) =
  {
    {
      local d = {  }
      for (i: 1 .. keys.listLen() step 1) {
        d.set(keys[i], values[i])
      }
      d
    }
  }

1. Define zipToDict(keys, values): creates dict from two parallel lists.
2. Loop i from 1 to keys length.
3. Set keys[i] → values[i] in result dict.

func compact(list) =
