func bstContains(tree, val) =
  {
    if (!tree ? dict) {
      false
    } else if (tree.get("val", []) == val) {
      true
    } else if (val < tree.get("val", [])) {
      bstContains(tree.get("left", false), val)
    } else {
      bstContains(tree.get("right", false), val)
    }
  }

Goal: Check if a BST (binary search tree represented as nested dicts) contains a given value.

1. The tree is a dict with keys "val", "left", "right".
2. If tree is not a dict (it's a leaf stub or false), return false — value not found.
3. If tree's "val" equals the target, return true.
4. If target < tree's val, search the left subtree.
5. Otherwise search the right subtree.
6. This works because BSTs guarantee smaller values are on the left, larger on the right.

func mergeCount(arr) =
  {
    if (arr.listLen() <= 1) {
        local listResult = [arr, 0]
        listResult
    } else {
      local mid = floor(arr.listLen() / 2)
      local left = arr.slice(1, mid)
      local right = arr.slice(mid + 1, arr.listLen())
      local lr = mergeCount(left)
      local rr = mergeCount(right)
      local lSorted = lr[1]
      local rSorted = rr[1]
      local inv = lr[2] + rr[2]
      local merged = []
      local i = 1
      local j = 1
      while (i <= lSorted.listLen() && j <= rSorted.listLen()) {
        if (lSorted[i] <= rSorted[j]) {
          merged.add(lSorted[i])
          i = i + 1
        } else {
          merged.add(rSorted[j])
          inv = inv + lSorted.listLen() - i + 1
          j = j + 1
        }
      }
      while (i <= lSorted.listLen()) {
        merged.add(lSorted[i])
        i = i + 1
      }
      while (j <= rSorted.listLen()) {
        merged.add(rSorted[j])
        j = j + 1
      }
        local listResult = [merged, inv]
        listResult
    }
  }

