func kirchhoff(adj, n) =
  {
    {
      local L = []
      for (i: 1 .. n step 1) {
        local row = []
        for (j: 1 .. n step 1) {
          row.add(0)
        }
        L.add(row)
      }
      for (i: 1 .. n step 1) {
        for (j: 1 .. n step 1) {
          if (adj[i][j] == 1) {
            L[i][i] = L[i][i] + 1
            L[i][j] = L[i][j] - 1
          }
        }
      }
      local M = []
      for (i: 1 .. n - 1 step 1) {
        local row = []
        for (j: 1 .. n - 1 step 1) {
          row.add(L[i][j])
        }
        M.add(row)
      }
      local det = 0
      if (M.listLen() == 2) {
        det = M[1][1] * M[2][2] - M[1][2] * M[2][1]
      } else if (M.listLen() == 3) {
        det = M[1][1] * (M[2][2] * M[3][3] - M[2][3] * M[3][2]) - M[1][2] * (M[2][1] * M[3][3] - M[2][3] * M[3][1]) + M[1][3] * (M[2][1] * M[3][2] - M[2][2] * M[3][1])
      } else {
        det = M[1][1]
      }
      round(abs(det))
    }
  }

