func mobiusFn(n) =
  {
    if (n == 1) {
      1
    } else {
      local factors = []
      local x = n
      local d = 2
      local squareFree = true
      while (d * d <= x) {
        if (x % d == 0) {
          factors.add(d)
          x = floor(x / d)
          if (x % d == 0) {
            squareFree = false
          }
        }
        d = d + 1
      }
      if (x > 1) {
        factors.add(x)
      }
      if (!squareFree) {
        0
      } else {
        -1 ^ factors.listLen()
      }
    }
  }

