    local sum = 0
    local i = 1
    local cont = true
    while (cont) {
      local g1 = i * (3 * i - 1) / 2
      local g2 = i * (3 * i + 1) / 2
      local sign = if (mod(i, 2) == 1) {
        1
      } else {
        -1
      }
      if (g1 <= k - 1) {
        sum = sum + sign * p[k - g1]
      }
      if (g2 <= k - 1) {
        sum = sum + sign * p[k - g2]
      }
      if (g1 > k - 1 && g2 > k - 1) {
        cont = false
      }
      i = i + 1
    }
    p[k] = sum
  }
  partitionDict.set(n, p[n + 1])
}
