func eulerPhi(n) =
  {
    {
      local result = n
      local x = n
      local d = 2
      while (d * d <= x) {
        if (x % d == 0) {
          while (x % d == 0) {
            x = floor(x / d)
          }
          result = result - floor(result / d)
        }
        d = d + 1
      }
      if (x > 1) {
        result = result - floor(result / x)
      }
      result
    }
  }

