func composeListOps(list, ops) =
  {
    {
      local result = copyList(list)
      for (op in ops) {
        local name = op.get("op", "")
        local arg = op.get("arg", 0)
        if (name === "map") {
          if (arg === "double") {
            result = result
              .map { x -> x * 2 }
          } else if (arg === "square") {
            result = result
              .map { x -> x * x }
          }
        } else if (name === "filter") {
          if (arg === "even") {
            result = result
              .filter { x -> mod(x, 2) == 0 }
          } else if (arg === "positive") {
            result = result
              .filter { x -> x > 0 }
          }
        } else if (name === "sort") {
          result = result.sort()
        } else if (name === "reverse") {
          result = result.reverseList()
        } else if (name === "reduce") {
          if (arg === "sum") {
            result = [result
              .reduce(0) { x, acc -> x + acc }]
          }
        }
      }
      result
    }
  }

