func selectionSort(list) =
  {
    {
      local remaining = copyList(list)
      local sorted = []
      while (remaining.listLen() > 0) {
        local minVal = remaining[1]
        local minIdx = 1
        for (i: 2 .. remaining.listLen() step 1) {
          if (remaining[i] < minVal) {
            minVal = remaining[i]
            minIdx = i
          }
        }
        sorted.add(minVal)
        remaining.remove(minIdx)
      }
      sorted
    }
  }

