func makeHeatmap(values) =
  {
      local stops = [makeColor([0, 0, 255]), makeColor([0, 255, 255]), makeColor([0, 255, 0]), makeColor([255, 255, 0]), makeColor([255, 0, 0])]
      values
        .map { v -> {
        local t = if (v < 0) {
          0
        } else if (v > 1) {
          1
        } else {
          v
        }
        local seg = floor(t * 4)
        if (seg >= 4) {
          seg = 3
        }
          local lt = t * 4 - seg
          local c1 = splitColor(stops[seg + 1])
          local c2 = splitColor(stops[seg + 2])
          local r = round(c1[2] * (1 - lt) + c2[2] * lt)
          local g = round(c1[3] * (1 - lt) + c2[3] * lt)
          local b = round(c1[4] * (1 - lt) + c2[4] * lt)
          makeColor([r, g, b])
      } }
  }

println(makeHeatmap([0, 0.25, 0.5, 0.75, 1.0]))

Goal: Map values in [0,1] to colors on a heatmap gradient.

1. Define 5 color stops: blue → cyan → green → yellow → red.
2. For each value v, clamp to [0,1], then find which segment of the gradient it falls in.
3. seg = floor(v * 4), clamped to [0,3] — selects which adjacent stop pair to interpolate.
4. lt = fractional position within that segment.
5. Interpolate R, G, B channels separately between the two stop colors.
6. Return makeColor([r, g, b]).

Output
```
[#FF00FFFF, #FFFFFFFF, #FFFF00FF, #FFFF00FF, #FF0000FF]
```

