        for (i: 1 .. row.listLen() step 1) {
          local len = row[i].textLen()
          while (colWidths.listLen() < i) {
            colWidths.add(0)
          }
          if (len > colWidths[i]) {
            colWidths[i] = len
          }
        }
      }
      local lines = []
      for (row in rows) {
        local cells = []
        for (i: 1 .. row.listLen() step 1) {
          local cell = row[i]
          while (cell.textLen() < colWidths[i]) {
            cell = cell _ " "
          }
          cells.add(cell)
        }
        lines.add(cells.join(" | "))
      }
      lines.join("\\n")
    }
  }

