func lzwCompress(s) =
  {
    {
      local dict = {  }
      local alpha = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ "
      for (i: 1 .. alpha.textLen() step 1) {
        dict.set(alpha.segment(i, 1), i - 1)
      }
      local codes = []
      local current = ""
      local nextCode = alpha.textLen()
      for (i: 1 .. s.textLen() step 1) {
        local ch = s.segment(i, 1)
        local combined = current _ ch
        if (dict.containsKey(combined)) {
          current = combined
        } else {
          codes.add(dict.get(current, 0))
          dict.set(combined, nextCode)
          nextCode = nextCode + 1
          current = ch
        }
      }
      if (current.textLen() > 0) {
        codes.add(dict.get(current, 0))
      }
      codes
    }
  }

