func matrixChainOrder(dims) =
  {
    {
      local n = dims.listLen() - 1
      local dp = []
      for (i: 1 .. n step 1) {
        local row = []
        for (j: 1 .. n step 1) {
          row.add(0)
        }
        dp.add(row)
      }
      for (len: 2 .. n step 1) {
        for (i: 1 .. n - len + 1 step 1) {
          local j = i + len - 1
          dp[i][j] = 999999999
          for (k: i .. j - 1 step 1) {
            local cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]
            if (cost < dp[i][j]) {
              dp[i][j] = cost
            }
          }
        }
      }
      dp[1][n]
    }
  }

