global ackCache = {  }
func ackermann(m, n) =
  {
    {
      local key = m _ "," _ n
      if (this.ackCache.containsKey(key)) {
        this.ackCache.get(key, 0)
      } else {
        local result = 0
        if (m == 0) {
          result = n + 1
        } else if (n == 0) {
          result = ackermann(m - 1, 1)
        } else {
          result = ackermann(m - 1, ackermann(m, n - 1))
        }
        this.ackCache.set(key, result)
        result
      }
    }
  }

