func colorClustering(colors, k) =
  {
    {
      local centers = []
      for (i: 1 .. k step 1) {
        centers.add(colors[i])
      }
      for (iter: 1 .. 5 step 1) {
        local assignments = []
        for (c in colors) {
          local best = 1
          local bestD = colorDistance(c, centers[1])
          for (j: 2 .. k step 1) {
            local d = colorDistance(c, centers[j])
            if (d < bestD) {
              bestD = d
              best = j
            }
          }
          assignments.add(best)
        }
        local newCenters = []
        for (j: 1 .. k step 1) {
          local rSum = 0
          local gSum = 0
          local bSum = 0
          local cnt = 0
          for (ci: 1 .. colors.listLen() step 1) {
            if (assignments[ci] == j) {
              local comp = splitColor(colors[ci])
              rSum = rSum + comp[2]
              gSum = gSum + comp[3]
              bSum = bSum + comp[4]
              cnt = cnt + 1
            }
          }
          if (cnt > 0) {
            newCenters.add(makeColor([round(rSum / cnt), round(gSum / cnt), round(bSum / cnt)]))
          } else {
            newCenters.add(centers[j])
          }
        }
        centers = newCenters
      }
      centers
    }
  }

