func buildPathWithBFS(grid, size, sR, sC, eR, eC) =
  {
    {
      local queue = [[sR, sC]]
      local visited = {  }
      local cameFrom = {  }
      visited.set(sR _ "," _ sC, true)
      local found = false
      while (queue.listLen() > 0 && (!found)) {
        local cur = queue[1]
        queue.remove(1)
        local r = cur[1]
        local c = cur[2]
        if (r == eR && c == eC) {
          found = true
        } else {
          local dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]]
          for (d in dirs) {
            local nr = r + d[1]
            local nc = c + d[2]
            local nk = nr _ "," _ nc
            if (nr >= 1 && nr <= size && nc >= 1 && nc <= size && grid[nr][nc] == 0 && (!visited.containsKey(nk))) {
              visited.set(nk, true)
              cameFrom.set(nk, [r, c])
              queue.add([nr, nc])
            }
          }
        }
      }
      local path = []
      if (found) {
        local cur = [eR, eC]
        while ((!cur[1]) == sR && cur[2] == sC) {
          path.add(cur)
          cur = cameFrom.get(cur[1] _ "," _ cur[2], [sR, sC])
        }
        path.add([sR, sC])
        path = path.reverseList()
      }
      path
    }
  }

