func heapPush(heap, val) {
  heap.add(val)
  local i = heap.listLen()
  while (i > 1 && heap[floor(i / 2)] > heap[i]) {
    local temp = heap[floor(i / 2)]
    heap[floor(i / 2)] = heap[i]
    heap[i] = temp
    i = floor(i / 2)
  }
}
func heapPop(heap) =
  {
    {
      local mn = heap[1]
      heap[1] = heap[heap.listLen()]
      heap.remove(heap.listLen())
      local i = 1
      while (i * 2 <= heap.listLen()) {
        local mc = i * 2
        if (mc + 1 <= heap.listLen() && heap[mc + 1] < heap[mc]) {
          mc = mc + 1
        }
        if (heap[i] <= heap[mc]) {
          break
        }
        local temp = heap[i]
        heap[i] = heap[mc]
        heap[mc] = temp
        i = mc
      }
      mn
    }
  }

local myHeap = []
heapPush(myHeap, 3)
heapPush(myHeap, 1)
heapPush(myHeap, 2)
println(heapPop(myHeap))

