func jacobiSymbol(a, n) =
  {
    {
      local a_val = a % n
      local n_val = n
      local t = 1
      while (a_val != 0) {
        while (a_val % 2 == 0) {
          a_val = a_val / 2
          local r = n_val % 8
          if (r == 3 || r == 5) {
            t = -t
          }
        }
        local temp = a_val
        a_val = n_val
        n_val = temp
        if (a_val % 4 == 3 && n_val % 4 == 3) {
          t = -t
        }
        a_val = a_val % n_val
      }
      if (n_val == 1) {
        t
      } else {
        0
      }
    }
  }

println(jacobiSymbol(2, 15))

