  {
    {
      local blocks = []
      for (i: 1 .. floor(plaintext.listLen() / 4) step 1) {
        blocks.add(plaintext.slice((i - 1) * 4 + 1, i * 4))
      }
      local encrypted = []
      local prev = copyList(iv)
      for (block in blocks) {
        local xored = xorBlock(block, prev)
        local enc = xored
          .map { b -> mod(b ~ key[1], 256) }
        encrypted.add(enc)
        prev = enc
      }
      encrypted
    }
  }

