          b = newA
          steps = steps + 1
          if (a[1] * a[1] + a[2] * a[2] <= b[1] * b[1] + b[2] * b[2]) {
            steps = 20
          }
        }
      }
        local listResult = [a, b]
        listResult
    }
  }

