func hmacSHA256_simple(key, message) =
  {
    {
      local ipad = key
        .map { b -> b ~ 54 }
      local opad = key
        .map { b -> b ~ 92 }
      local inner = 0
      for (b in ipad) {
        inner = mod(inner * 31 + b, 4294967296)
      }
      for (b in message) {
        inner = mod(inner * 31 + b, 4294967296)
      }
      local outer = 0
      for (b in opad) {
        outer = mod(outer * 31 + b, 4294967296)
      }
      outer = mod(outer * 31 + inner, 4294967296)
      outer
    }
  }

