func predict(gp, x_new) =
  {
    {
      local xs = gp.get("xs", [])
      local ys = gp.get("ys", [])
      local n = xs.listLen()
      local k_star = xs
        .map { xi -> squaredExpKernel(x_new, xi) }
      local K = []
      for (i: 1 .. n step 1) {
        local row = []
        for (j: 1 .. n step 1) {
          row.add(squaredExpKernel(xs[i], xs[j]) + (if (i == j) {
            0.000001
          } else {
            0
          }))
        }
        K.add(row)
      }
      local w = k_star
      local mean_pred = 0
      for (i: 1 .. n step 1) {
        mean_pred = mean_pred + w[i] * ys[i]
      }
      mean_pred
    }
  }

