func numericalIntegral_simpson(f_name, a, b, n) =
  {
    {
      local h = (b - a) / n
      local sum_s = 0
      for (i: 0 .. n step 1) {
        local x = a + i * h
        local fx = sin(x)
        local w = if (i == 0 || i == n) {
          1
        } else if (i % 2 == 1) {
          4
        } else {
          2
        }
        sum_s = sum_s + w * fx
      }
      sum_s * h / 3
    }
  }

