func secant(f_name, x0, x1, tol, maxIter) =
  {
    {
      local a = x0
      local b = x1
      local iter_s = 0
      local root = b
      while (iter_s < maxIter) {
        local fa = a ^ 3 - a - 2
        local fb = b ^ 3 - b - 2
        if (abs(fb - fa) < 0.000000000000001) {
          iter_s = maxIter
        }
        root = b - fb * (b - a) / (fb - fa)
        a = b
        b = root
        iter_s = iter_s + 1
        if (abs(b - a) < tol) {
          iter_s = maxIter
        }
      }
      root
    }
  }

