func qrDecompose(A) =
  {
    {
      local n = A.listLen()
      local m = A[1].listLen()
      local Q = []
      local R_qr = []
      for (i: 1 .. n step 1) {
        local row = []
        for (j: 1 .. m step 1) {
          row.add(0)
        }
        Q.add(row)
        R_qr.add(copyList(row))
      }
      local cols = []
      for (j: 1 .. m step 1) {
        local col = []
        for (i: 1 .. n step 1) {
          col.add(A[i][j])
        }
        cols.add(col)
      }
      local q_cols = []
      for (j: 1 .. m step 1) {
        local v = copyList(cols[j])
        for (k: 1 .. j - 1 step 1) {
          local dot = 0
          for (i: 1 .. n step 1) {
            dot = dot + q_cols[k][i] * cols[j][i]
          }
          R_qr[k][j] = dot
          for (i: 1 .. n step 1) {
            v[i] = v[i] - dot * q_cols[k][i]
          }
        }
        local norm_v = sqrt(v
          .reduce(0) { x, s -> x * x + s })
        R_qr[j][j] = norm_v
        local qj = v
          .map { vi -> vi / norm_v }
        q_cols.add(qj)
      }
      for (j: 1 .. m step 1) {
        for (i: 1 .. n step 1) {
          Q[i][j] = q_cols[j][i]
        }
      }
      { "Q" : Q, "R" : R_qr }
    }
  }

