func buildCFD(mesh, Re, scheme) =
  {
    { "mesh" : mesh, "Re" : Re, "scheme" : scheme, "u" : mesh
      .map { x -> 0 } }
  }

func stepCFD(cfd, dt) =
  {
    {
      local u = cfd.get("u", [])
      local n = u.listLen()
      local dx = 1.0 / (n - 1)
      local Re = cfd.get("Re", [])
      local u_new = copyList(u)
      for (i: 2 .. n - 1 step 1) {
        local conv = u[i] * (u[i] - u[i - 1]) / dx
        local diff = ((u[i + 1] - 2 * u[i] + u[i - 1]) / Re * dx) ^ 2
        u_new[i] = u[i] + dt * (-conv + diff)
      }
      cfd.set("u", u_new)
      cfd
    }
  }

func convergenceCFD(cfd) =
  {
      local u = cfd.get("u", [])
      local mean_u = u
        .reduce(0) { x, s -> x + s } / u.listLen()
      abs(mean_u)
  }

