func markSweep() =
  {
    for (obj in this.gcHeap) {
      obj.set("alive", false)
    }
    for (rootId in this.gcRoots) {
      for (obj in this.gcHeap) {
        if (obj.get("id", []) === rootId) {
          obj.set("alive", true)
        }
      }
    }
    local swept = this.gcHeap
      .filter { obj -> obj.get("alive", []) }
    this.gcHeap = swept
    swept
  }

