        for (j: 1 .. n step 1) {
          row.add(0)
        }
        C.add(row)
      }
      for (i: 1 .. n - 1 step 1) {
        C[i + 1][i] = 1
      }
      local lead = poly[n + 1]
      for (j: 1 .. n step 1) {
        C[j][n] = -poly[j] / lead
      }
      C
    }
  }

