      for (i: 1 .. instructions.listLen() step 1) {
        local instr = instructions[i]
        if (instr.startsWith("JMP ") || instr.startsWith("BNE ") || instr.startsWith("BEQ ")) {
          local parts = instr.split(" ")
          local label = parts[2]
          if (label_map.containsKey(label)) {
            local offset = label_map.get(label, []) - i
            patched.add(parts[1] _ " " _ offset)
          } else {
            patched.add(instr)
          }
        } else {
          patched.add(instr)
        }
      }
      patched
    }
  }

