func mergeSortHelper(list) =
  {
    if (list.listLen() <= 1) {
      list
    } else {
      local mid = floor(list.listLen() / 2)
      local left = mergeSortHelper(list.slice(1, mid))
      local right = mergeSortHelper(list.slice(mid + 1, list.listLen()))
      local res = []
      local i = 1
      local j = 1
      while (i <= left.listLen() && j <= right.listLen()) {
        if (left[i] < right[j]) {
          res.add(left[i])
          i = i + 1
        } else {
          res.add(right[j])
          j = j + 1
        }
      }
      while (i <= left.listLen()) {
        res.add(left[i])
        i = i + 1
      }
      while (j <= right.listLen()) {
        res.add(right[j])
        j = j + 1
      }
      res
    }
  }

