func applySplashDamage(enemies, epicenter, radius, damage) =
  {
    {
      local ex = epicenter[1]
      local ey = epicenter[2]
      local updated = []
      for (enemy in enemies) {
        local dx = enemy.get("x", 0) - ex
        local dy = enemy.get("y", 0) - ey
        local dist = sqrt(dx * dx + dy * dy)
        if (dist <= radius) {
          local falloff = 1 - dist / radius
          local dmg = round(damage * falloff)
          local newHp = enemy.get("hp", 0) - dmg
          local e2 = copyDict(enemy)
          e2.set("hp", newHp)
          updated.add(e2)
        } else {
          updated.add(enemy)
        }
      }
      updated
    }
  }

