func pacManPath(grid, px, py, fx, fy) =
  {
    {
      local rows = grid.listLen()
      local cols = grid[1].listLen()
      local visited = []
      local queue = [[px, py, 0]]
      visited.add(px _ "," _ py)
      local result = -1
      local found = false
      while (queue.listLen() > 0 && (!found)) {
        local cur = queue[1]
        queue.remove(1)
        local cx = cur[1]
        local cy = cur[2]
        local cd = cur[3]
        if (cx == fx && cy == fy) {
          result = cd
          found = true
        } else {
          local dirs = [[0, 1], [0, -1], [1, 0], [-1, 0]]
          for (d in dirs) {
            local nx = cx + d[1]
            local ny = cy + d[2]
            local key = nx _ "," _ ny
            if (nx >= 1 && nx <= rows && ny >= 1 && ny <= cols && grid[nx][ny] != 1 && (!visited.containsItem(key))) {
              visited.add(key)
              queue.add([nx, ny, cd + 1])
            }
          }
        }
      }
      result
    }
  }

