      for (trial: 1 .. 100 step 1) {
        local activeEdges = {  }
        for (nd in nodes) {
          activeEdges.set(nd, [])
        }
        for (e in edges) {
          if (randFloat() < p) {
            activeEdges.get(e[1], []).add(e[2])
            activeEdges.get(e[2], []).add(e[1])
          }
