          minW = w
        }
        if (w > maxW) {
          maxW = w
        }
      }
      local palette = {  }
      for (e, w in weights) {
        local t = if (maxW == minW) {
          0
        } else {
          (w - minW) / (maxW - minW)
        }
        local r = round(t * 255)
        local g = round((1 - t) * 255)
        palette.set(e, makeColor([r, g, 0]))
      }
