func kmpSearchList(text_chars, pattern_chars) =
  {
    {
      local m = pattern_chars.listLen()
      local n = text_chars.listLen()
      local fail = []
      for (i: 1 .. m step 1) {
        fail.add(0)
      }
      local k = 0
      for (i: 2 .. m step 1) {
        while (k > 0 && pattern_chars[k + 1] !== pattern_chars[i]) {
          k = fail[k]
        }
        if (pattern_chars[k + 1] === pattern_chars[i]) {
          k = k + 1
        }
        fail[i] = k
      }
      local matches = []
      k = 0
      for (i: 1 .. n step 1) {
        while (k > 0 && pattern_chars[k + 1] !== text_chars[i]) {
          k = fail[k]
        }
        if (pattern_chars[k + 1] === text_chars[i]) {
          k = k + 1
        }
        if (k == m) {
          matches.add(i - m + 1)
          k = fail[k]
        }
      }
      matches
    }
  }

