func longestPalindrome(s) =
  {
    {
      local t = "#"
      for (i: 1 .. s.textLen() step 1) {
        t = t _ s.segment(i, 1) _ "#"
      }
      local n = t.textLen()
      local p = []
      for (i: 1 .. n step 1) {
        p.add(0)
      }
      local c = 1
      local r = 1
      for (i: 2 .. n step 1) {
        local mirror = 2 * c - i
        if (i < r && mirror >= 1) {
          p[i] = if (r - i < p[mirror]) {
            r - i
          } else {
            p[mirror]
          }
        }
        local a = i - p[i] + 1
        local b = i + p[i] + 1
        while (a >= 1 && b <= n && t.segment(a, 1) === t.segment(b, 1)) {
          p[i] = p[i] + 1
          a = a - 1
          b = b + 1
        }
        if (i + p[i] > r) {
          c = i
          r = i + p[i]
        }
      }
      local maxLen = 0
      local center = 1
      for (i: 1 .. n step 1) {
        if (p[i] > maxLen) {
          maxLen = p[i]
          center = i
        }
      }
        local start = floor((center - maxLen) / 2) + 1
        s.segment(start, maxLen)
    }
  }

