func jaroWinkler(s1, s2) =
  {
    {
      local l1 = s1.textLen()
      local l2 = s2.textLen()
      if (l1 == 0 && l2 == 0) {
        1
      } else {
        local matchWindow = floor(if (l1 > l2) {
          l1
        } else {
          l2
        }) / 2 - 1
        local s1matched = []
        local s2matched = []
        for (i: 1 .. l1 step 1) {
          s1matched.add(false)
        }
        for (i: 1 .. l2 step 1) {
          s2matched.add(false)
        }
        local matches = 0
        for (i: 1 .. l1 step 1) {
          local start = if (i - matchWindow > 1) {
            round(i - matchWindow)
          } else {
            1
          }
          local end = if (i + matchWindow < l2) {
            round(i + matchWindow)
          } else {
            l2
          }
          for (j: start .. end step 1) {
            if ((!s2matched[j]) && s1.segment(i, 1) === s2.segment(j, 1)) {
              s1matched[i] = true
              s2matched[j] = true
              matches = matches + 1
              j = end + 1
            }
          }
        }
        if (matches == 0) {
          0
        } else {
          local trans = 0
          local k = 1
          for (i: 1 .. l1 step 1) {
            if (s1matched[i]) {
              while (!s2matched[k]) {
                k = k + 1
              }
              if (s1.segment(i, 1) !== s2.segment(k, 1)) {
                trans = trans + 1
              }
              k = k + 1
            }
          }
          local jaro = (matches / l1 + matches / l2 + (matches - trans / 2) / matches) / 3
          local prefix = 0
          for (i: 1 .. 4 step 1) {
            if (i <= l1 && i <= l2 && s1.segment(i, 1) === s2.segment(i, 1)) {
              prefix = prefix + 1
            }
          }
          jaro + prefix * 0.1 * (1 - jaro)
        }
      }
    }
  }

func findMostSimilar(word, candidates) =
  {
    {
      local best = -1
      local bestWord = ""
      for (c in candidates) {
        local score = jaroWinkler(word, c)
        if (score > best) {
          best = score
          bestWord = c
        }
      }
