func decompressString(s) =
  {
    {
      local stack = []
      local currentStr = ""
      local currentNum = 0
      for (i: 1 .. s.textLen() step 1) {
        local ch = s.segment(i, 1)
        if (ch ? number) {
          currentNum = currentNum * 10 + ch
        } else if (ch === "[") {
          stack.add([currentNum, currentStr])
          currentStr = ""
          currentNum = 0
        } else if (ch === "]") {
          local top = stack[stack.listLen()]
          stack.remove(stack.listLen())
          local times = top[1]
          local prev = top[2]
          local repeated = ""
          for (k: 1 .. times step 1) {
            repeated = repeated _ currentStr
          }
          currentStr = prev _ repeated
        } else {
          currentStr = currentStr _ ch
        }
      }
      currentStr
    }
  }

