func jaroSimilarity(s1, s2) =
  {
    {
      local l1 = s1.textLen()
      local l2 = s2.textLen()
      local matchWindow = floor((if (l1 > l2) {
        l1
      } else {
        l2
      }) / 2) - 1
      local s1matched = []
      local s2matched = []
      for (i: 1 .. l1 step 1) {
        s1matched.add(false)
      }
      for (i: 1 .. l2 step 1) {
        s2matched.add(false)
      }
      local matches = 0
      for (i: 1 .. l1 step 1) {
        local lo = if (i - matchWindow > 1) {
          i - matchWindow
        } else {
          1
        }
        local hi = if (i + matchWindow < l2) {
          i + matchWindow
        } else {
          l2
        }
        for (j: lo .. hi step 1) {
          if ((!s2matched[j]) && (!s1matched[i]) && s1.segment(i, 1) === s2.segment(j, 1)) {
            s1matched[i] = true
            s2matched[j] = true
            matches = matches + 1
          }
        }
      }
      if (matches == 0) {
        0
      } else {
        local trans = 0
        local k = 1
        for (i: 1 .. l1 step 1) {
          if (s1matched[i]) {
            while (k <= l2 && (!s2matched[k])) {
              k = k + 1
            }
            if (k <= l2 && s1.segment(i, 1) !== s2.segment(k, 1)) {
              trans = trans + 1
            }
            k = k + 1
          }
        }
        (matches / l1 + matches / l2 + (matches - trans / 2) / matches) / 3
      }
    }
  }

