        while (freq.get(w, 0) > 1) {
          local lw = words[left]
          freq.set(lw, freq.get(lw, 0) - 1)
          if (freq.get(lw, 0) == 0) {
            freq.delete(lw)
          }
          left = left + 1
        }
        if (right - left + 1 > maxLen) {
          maxLen = right - left + 1
        }
      }
      maxLen
    }
  }

