func computeSDF(polygons, queryPt) =
  {
    {
      local minDist = 999999
      local inside = false
      for (poly in polygons) {
        local n = poly.listLen()
        local isInside = false
        local px = queryPt[1]
        local py = queryPt[2]
        local j = n
        for (i: 1 .. n step 1) {
          local xi = poly[i][1]
          local yi = poly[i][2]
          local xj = poly[j][1]
          local yj = poly[j][2]
          if (yi > py != yj > py && px < (xj - xi) * (py - yi) / (yj - yi) + xi) {
            isInside = !isInside
          }
          local dx = poly[i][1] - px
          local dy = poly[i][2] - py
          local d = sqrt(dx * dx + dy * dy)
          if (d < minDist) {
            minDist = d
          }
          j = i
        }
        if (isInside) {
          inside = true
        }
      }
      if (inside) {
        -minDist
      } else {
        minDist
      }
    }
  }

