func buildGridNeighbors(rows, cols) =
  {
    {
      local result = {  }
      for (r: 1 .. rows step 1) {
        for (c: 1 .. cols step 1) {
          local key = r _ "," _ c
          local neighbors = []
          if (r > 1) {
            neighbors.add(r - 1 _ "," _ c)
          }
          if (r < rows) {
            neighbors.add(r + 1 _ "," _ c)
          }
          if (c > 1) {
            neighbors.add(r _ "," _ c - 1)
          }
          if (c < cols) {
            neighbors.add(r _ "," _ c + 1)
          }
          result.set(key, neighbors)
        }
      }
      result
    }
  }

