func mergeSegments(segments) =
  {
    {
      local merged = copyList(segments)
      local changed = true
      while (changed) {
        changed = false
        local newMerged = []
        local used = []
        for (i: 1 .. merged.listLen() step 1) {
          if (!used.containsItem(i)) {
            local seg = merged[i]
            for (j: i + 1 .. merged.listLen() step 1) {
              if (!used.containsItem(j)) {
                local s2 = merged[j]
                if (seg[2] >= s2[1] && seg[1] <= s2[2]) {
                  seg = [if (seg[1] < s2[1]) {
                    seg[1]
                  } else {
                    s2[1]
                  }, if (seg[2] > s2[2]) {
                    seg[2]
                  } else {
                    s2[2]
                  }]
                  used.add(j)
                  changed = true
                }
              }
            }
            newMerged.add(seg)
          }
        }
        merged = newMerged
      }
      merged
    }
  }

