func jarvisMarchStep(pts, current) =
  {
    {
      local best = 0
      for (i: 2 .. pts.listLen() step 1) {
        if (best == 0 || best == current) {
          best = i
        } else {
          local ax = pts[best][1] - pts[current][1]
          local ay = pts[best][2] - pts[current][2]
          local bx = pts[i][1] - pts[current][1]
          local by = pts[i][2] - pts[current][2]
          local cross = ax * by - ay * bx
          if (cross < 0) {
            best = i
          }
        }
      }
      best
    }
  }

