func douglasPeucker(pts, epsilon) =
  {
    if (pts.listLen() <= 2) {
      pts
    } else {
      local ax = pts[1][1]
      local ay = pts[1][2]
      local bx = pts[pts.listLen()][1]
      local by = pts[pts.listLen()][2]
      local maxDist = 0
      local maxIdx = 1
      for (i: 2 .. pts.listLen() - 1 step 1) {
        local dx = bx - ax
        local dy = by - ay
        local len = sqrt(dx * dx + dy * dy)
        local d = if (len == 0) {
          0
        } else {
          abs((pts[i][1] - ax) * dy - (pts[i][2] - ay) * dx) / len
        }
        if (d > maxDist) {
          maxDist = d
          maxIdx = i
        }
      }
      if (maxDist > epsilon) {
        local left = douglasPeucker(pts.slice(1, maxIdx), epsilon)
        local right = douglasPeucker(pts.slice(maxIdx, pts.listLen()), epsilon)
        local result = copyList(left)
        for (i: 2 .. right.listLen() step 1) {
          result.add(right[i])
        }
        result
      } else {
          local listResult = [pts[1], pts[pts.listLen()]]
          listResult
      }
    }
  }

