func evalRPN(tokens) =
  {
    {
      local stack = []
      for (t in tokens) {
        if (t === "+") {
          local b = stack[stack.listLen()]
          stack.remove(stack.listLen())
          local a = stack[stack.listLen()]
          stack.remove(stack.listLen())
          stack.add(a + b)
        } else if (t === "-") {
          local b = stack[stack.listLen()]
          stack.remove(stack.listLen())
          local a = stack[stack.listLen()]
          stack.remove(stack.listLen())
          stack.add(a - b)
        } else if (t === "*") {
          local b = stack[stack.listLen()]
          stack.remove(stack.listLen())
          local a = stack[stack.listLen()]
          stack.remove(stack.listLen())
          stack.add(a * b)
        } else if (t === "/") {
          local b = stack[stack.listLen()]
          stack.remove(stack.listLen())
          local a = stack[stack.listLen()]
          stack.remove(stack.listLen())
          stack.add(a / b)
        } else {
          stack.add(t * 1)
        }
      }
      stack[1]
    }
  }

