func formatThousands(n) =
  {
    {
      local s = "" _ n
      local result = ""
      local len = s.textLen()
      for (i: 1 .. len step 1) {
        result = result _ s.segment(i, 1)
        local remaining = len - i
        if (remaining > 0 && remaining % 3 == 0) {
          result = result _ ","
        }
      }
      result
    }
  }

