global lruVals = {  }
global lruOrder = []
global lruCap = 3
func lruGet(k) =
  {
    {
      local key = "" _ k
      if (this.lruVals.containsKey(key)) {
        local idx = this.lruOrder.indexOf(key)
        if (idx > 0) {
          this.lruOrder.remove(idx)
          this.lruOrder.add(key)
        }
        this.lruVals.get(key, [])
      } else {
        -1
      }
    }
  }

func lruPut(k, v) {
  local key = "" _ k
  if (this.lruVals.containsKey(key)) {
    local idx = this.lruOrder.indexOf(key)
    if (idx > 0) {
      this.lruOrder.remove(idx)
    }
  } else if (this.lruOrder.listLen() >= this.lruCap) {
    local evict = this.lruOrder[1]
    this.lruOrder.remove(1)
    this.lruVals.delete(evict)
  }
  this.lruVals.set(key, v)
  this.lruOrder.add(key)
}
