func spiralOrder(n) {
  local mat = []
  for (i: 1 .. n step 1) {
    local row = []
    for (j: 1 .. n step 1) {
      row.add(0)
    }
    mat.add(row)
  }
  local top = 1
  local bottom = n
  local left = 1
  local right = n
  local num = 1
  while (num <= n * n) {
    for (c: left .. right step 1) {
      mat[top][c] = num
      num = num + 1
    }
    top = top + 1
    for (r: top .. bottom step 1) {
      mat[r][right] = num
      num = num + 1
    }
    right = right - 1
    for (c: right .. left step -1) {
      mat[bottom][c] = num
      num = num + 1
    }
    bottom = bottom - 1
    for (r: bottom .. top step -1) {
      mat[r][left] = num
      num = num + 1
    }
    left = left + 1
  }
  for (row in mat) {
    println(row)
  }
}
