          local c = pos[2]
          if (r >= 1 && r <= rows && c >= 1 && c <= cols && grid[r][c] == oldColor) {
            grid[r][c] = newColor
            queue.add([r - 1, c])
            queue.add([r + 1, c])
            queue.add([r, c - 1])
            queue.add([r, c + 1])
          }
        }
        grid
      }
    }
  }

