func naiveBayes(trainData, trainLabels, query) =
  {
    {
      local classes = {  }
      for (i: 1 .. trainLabels.listLen() step 1) {
        local label = trainLabels[i]
        if (!classes.containsKey(label)) {
          classes.set(label, { "count" : 0, "features" : {  } })
        }
        local c = classes.get(label, [])
        c.set("count", c.get("count", []) + 1)
        for (j: 1 .. trainData[i].listLen() step 1) {
          local fkey = "" _ j _ "_" _ trainData[i][j]
          c.get("features", []).set(fkey, if (c.get("features", []).containsKey(fkey)) {
            c.get("features", []).get(fkey, []) + 1
          } else {
            1
          })
        }
      }
      local total = trainLabels.listLen()
      local bestLabel = ""
      local bestScore = -999999
      for (label, info in classes) {
        local score = log(info.get("count", []) / total)
        for (j: 1 .. query.listLen() step 1) {
          local fkey = "" _ j _ "_" _ query[j]
          local cnt = if (info.get("features", []).containsKey(fkey)) {
            info.get("features", []).get(fkey, [])
          } else {
            0
          }
          score = score + log((cnt + 1) / (info.get("count", []) + 2))
        }
        if (score > bestScore) {
          bestScore = score
          bestLabel = label
        }
      }
      bestLabel
    }
  }

