func lcs321(a, b) =
  {
    {
      local m = a.textLen()
      local n = b.textLen()
      local dp = []
      for (i: 0 .. m step 1) {
        local row = []
        for (j: 0 .. n step 1) {
          row.add("")
        }
        dp.add(row)
      }
      for (i: 1 .. m step 1) {
        for (j: 1 .. n step 1) {
          if (a.segment(i, 1) === b.segment(j, 1)) {
            dp[i + 1][j + 1] = dp[i][j] _ a.segment(i, 1)
          } else {
            dp[i + 1][j + 1] = if (dp[i][j + 1].textLen() > dp[i + 1][j].textLen()) {
              dp[i][j + 1]
            } else {
              dp[i + 1][j]
            }
          }
        }
      }
      dp[m + 1][n + 1]
    }
  }

