func kmpSearch(text, pattern) =
  {
    {
      local n = text.textLen()
      local m = pattern.textLen()
      local lps = []
      for (i: 1 .. m step 1) {
        lps.add(0)
      }
      local len = 0
      local i = 2
      while (i <= m) {
        if (pattern.segment(i, 1) === pattern.segment(len + 1, 1)) {
          len = len + 1
          lps[i] = len
          i = i + 1
        } else if (len > 0) {
          len = lps[len]
        } else {
          lps[i] = 0
          i = i + 1
        }
      }
      local result = []
      local j = 1
      i = 1
      while (i <= n) {
        if (text.segment(i, 1) === pattern.segment(j, 1)) {
          i = i + 1
          j = j + 1
        }
        if (j > m) {
          result.add(i - m)
          j = lps[j - 1] + 1
        } else if (i <= n && text.segment(i, 1) !== pattern.segment(j, 1)) {
          if (j > 1) {
            j = lps[j - 1] + 1
          } else {
            i = i + 1
          }
        }
      }
      result
    }
  }

