func productExceptSelf(lst) =
  {
    {
      local n = lst.listLen()
      local left = []
      local right = []
      for (i: 1 .. n step 1) {
        left.add(1)
      }
      for (i: 1 .. n step 1) {
        right.add(1)
      }
      for (i: 2 .. n step 1) {
        left[i] = left[i - 1] * lst[i - 1]
      }
      for (i: n - 1 .. 1 step -1) {
        right[i] = right[i + 1] * lst[i + 1]
      }
      local result = []
      for (i: 1 .. n step 1) {
        result.add(left[i] * right[i])
      }
      result
    }
  }

