        for (k in a.keys()) {
          if ((!b.containsKey(k)) || (!deepEqual(a.get(k, []), b.get(k, [])))) {
            ok = false
          }
        }
        ok
      }
    } else if ((a ? list) && (b ? list)) {
      if (a.listLen() != b.listLen()) {
        false
      } else {
        local ok = true
        for (i: 1 .. a.listLen() step 1) {
          if (!deepEqual(a[i], b[i])) {
            ok = false
          }
        }
        ok
      }
    } else {
      a == b
    }
  }

