func diffPatch(v1, v2) =
  {
    {
      local changes = []
      for (k in v2.keys()) {
        if (!v1.containsKey(k)) {
          changes.add({ "path" : [k], "op" : "set", "value" : v2.get(k, []) })
        } else if ((v1.get(k, []) ? dict) && (v2.get(k, []) ? dict)) {
          local sub = diffPatch(v1.get(k, []), v2.get(k, []))
          for (c in sub) {
            local path = [k]
            path.appendList(c.get("path", []))
            changes.add({ "path" : path, "op" : c.get("op", []), "value" : c.get("value", []) })
          }
        } else if (v1.get(k, []) != v2.get(k, [])) {
          changes.add({ "path" : [k], "op" : "set", "value" : v2.get(k, []) })
        }
      }
      for (k in v1.keys()) {
        if (!v2.containsKey(k)) {
          changes.add({ "path" : [k], "op" : "delete", "value" : "" })
        }
      }
      changes
    }
  }

