func minimumWindowSubstring(s, t) =
  {
    {
      local need = {  }
      for (i: 1 .. t.textLen() step 1) {
        local ch = t.segment(i, 1)
        need.set(ch, if (need.containsKey(ch)) {
          need.get(ch, []) + 1
        } else {
          1
        })
      }
      local window = {  }
      local have = 0
      local required = need.dictLen()
      local lo = 1
      local result = ""
      local minLen = s.textLen() + 1
      for (hi: 1 .. s.textLen() step 1) {
        local ch = s.segment(hi, 1)
        window.set(ch, if (window.containsKey(ch)) {
          window.get(ch, []) + 1
        } else {
          1
        })
        if (need.containsKey(ch) && window.get(ch, []) == need.get(ch, [])) {
          have = have + 1
        }
        while (have == required) {
          if (hi - lo + 1 < minLen) {
            minLen = hi - lo + 1
            result = s.segment(lo, minLen)
          }
          local lch = s.segment(lo, 1)
          window.set(lch, window.get(lch, []) - 1)
          if (need.containsKey(lch) && window.get(lch, []) < need.get(lch, [])) {
            have = have - 1
          }
          lo = lo + 1
        }
      }
      result
    }
  }

