func longestBitonicSubsequence(lst) =
  {
    {
      local n = lst.listLen()
      local inc = []
      local dec = []
      for (i: 1 .. n step 1) {
        inc.add(1)
        dec.add(1)
      }
      for (i: 2 .. n step 1) {
        for (j: 1 .. i - 1 step 1) {
          if (lst[j] < lst[i] && inc[j] + 1 > inc[i]) {
            inc[i] = inc[j] + 1
          }
        }
      }
      for (i: n - 1 .. 1 step -1) {
        for (j: n .. i + 1 step -1) {
          if (lst[j] < lst[i] && dec[j] + 1 > dec[i]) {
            dec[i] = dec[j] + 1
          }
        }
      }
      local best = 1
      for (i: 1 .. n step 1) {
        best = max(best, inc[i] + dec[i] - 1)
      }
      best
    }
  }

