func binomCoeff(n, k) =
  {
    if (k > n) {
      0
    } else if (k == 0 || k == n) {
      1
    } else {
      local result = 1
      for (i: 1 .. min(k, n - k) step 1) {
        result = result * (n - i + 1) / i
      }
      result
    }
  }

func necklaces(n, k) =
  {
    {
      local total = 0
      for (d: 1 .. n step 1) {
        if (n % d == 0) {
          total = total + binomCoeff(d, round(k * d / n))
        }
      }
      round(total / n)
    }
  }

